define(["jquery"],function($){"use strict";return{init:function(){var html=document.documentElement,themeBtn=document.getElementById("erp-theme-toggle");function getTheme(){try{return localStorage.getItem("erp-moodle-theme")||"light"}catch(e){return"light"}}function setTheme(t){html.setAttribute("data-bs-theme",t);try{localStorage.setItem("erp-moodle-theme",t)}catch(e){}if(themeBtn){themeBtn.setAttribute("aria-pressed","dark"===t?"true":"false");themeBtn.setAttribute("title","dark"===t?"Switch to light theme":"Switch to dark theme")}}if(themeBtn){setTheme(getTheme());themeBtn.addEventListener("click",function(){setTheme("dark"===getTheme()?"light":"dark")})}var userBtn=document.getElementById("erp-user-btn"),userMenu=document.getElementById("erp-profile-menu");if(userBtn&&userMenu){function isOpen(){return userMenu.classList.contains("erp-pm-open")}function openMenu(){userMenu.classList.add("erp-pm-open");userBtn.setAttribute("aria-expanded","true");var f=userMenu.querySelector("a.erp-pm-item");if(f)f.focus()}function closeMenu(){userMenu.classList.remove("erp-pm-open");userBtn.setAttribute("aria-expanded","false")}userBtn.addEventListener("click",function(e){e.stopPropagation();isOpen()?closeMenu():openMenu()});document.addEventListener("click",function(e){if(!userBtn.contains(e.target)&&!userMenu.contains(e.target))closeMenu()});document.addEventListener("keydown",function(e){if("Escape"===e.key&&isOpen()){closeMenu();userBtn.focus()}});userMenu.addEventListener("keydown",function(e){var items=Array.prototype.slice.call(userMenu.querySelectorAll("a.erp-pm-item")),idx=items.indexOf(document.activeElement);if("ArrowDown"===e.key){e.preventDefault();items[idx<items.length-1?idx+1:0].focus()}else if("ArrowUp"===e.key){e.preventDefault();idx>0?items[idx-1].focus():(closeMenu(),userBtn.focus())}else if("Tab"===e.key)closeMenu()})}}};});